<script setup lang="ts">
import { useDocumentMetadata } from '@/composables/useDocumentMetadata';
import { ref, watch, computed, nextTick } from 'vue';
import { FolderIcon, MessageSquareIcon, ChevronRightIcon } from 'lucide-vue-next';
import type { ChatSummary } from '@/01-models/types';
import type { SearchResultItem } from '@/features/global-search/composables/useChatSearch';
import { useChatNavigation } from '@/composables/chat/ui/useChatNavigation';
import { useCurrentChatState } from '@/composables/chat/ui/useCurrentChatState';
import { useGlobalSearch } from '@/features/global-search/composables/useGlobalSearch';
import { useRouter } from 'vue-router';
import { scrollIntoViewSafe } from '@/utils/dom';
import SearchPreview from './SearchPreview.vue';
import { idToRaw } from '@/01-models/ids';
import type { ChatId } from '@/01-models/ids';
import { lazyStrings } from '@/strings';

const props = defineProps<{
  groupId: string,
  groupName: string,
}>();

const router = useRouter();
const { openChat } = useChatNavigation();
const documentMetadata = useDocumentMetadata();
const { closeSearch } = useGlobalSearch();
const { sidebarItems } = useCurrentChatState();

const chats = computed<ChatSummary[]>(() => {
  for (const item of sidebarItems.value) {
    if (item.type !== 'chat_group' || idToRaw({ id: item.chatGroup.id }) !== props.groupId) continue;
    return item.chatGroup.items
      .map(chatItem => chatItem.chat)
      .sort((left, right) => right.updatedAt - left.updatedAt);
  }
  return [];
});
const selectedChatId = ref<ChatId | null>(null);
const chatListContainer = ref<HTMLElement | null>(null);
const exposedSelectedChatId = computed(() => selectedChatId.value === null ? null : idToRaw({ id: selectedChatId.value }));

const selectedChat = computed(() => chats.value.find(c => c.id === selectedChatId.value) || null);

async function selectAndNavigate({ chatId }: { chatId: ChatId }) {
  documentMetadata?.finishHomeIntroduction();
  await openChat({ chatId });
  router.push(`/chat/${idToRaw({ id: chatId })}`);
  closeSearch();
}

const timeFormatter = new Intl.DateTimeFormat(undefined, {
  month: 'short',
  day: 'numeric',
});

function formatTime({ timestamp }: { timestamp: number }) {
  return timeFormatter.format(new Date(timestamp));
}

function navigate({ direction }: { direction: 'up' | 'down' }) {
  if (chats.value.length === 0) return;
  const currentIndex = chats.value.findIndex(c => c.id === selectedChatId.value);
  let nextIndex = currentIndex;

  switch (direction) {
  case 'up':
    nextIndex = Math.max(0, currentIndex - 1);
    break;
  case 'down':
    nextIndex = Math.min(chats.value.length - 1, currentIndex + 1);
    break;
  default: {
    const _ex: never = direction;
    throw new Error(`Unhandled direction: ${_ex}`);
  }
  }

  const nextChat = chats.value[nextIndex];
  if (nextChat) {
    selectedChatId.value = nextChat.id;
    // Ensure the selected item is visible
    nextTick(() => {
      if (!chatListContainer.value) return;
      const el = chatListContainer.value.querySelector(`[data-group-chat-id="${idToRaw({ id: nextChat.id })}"]`);
      if (el instanceof HTMLElement) {
        scrollIntoViewSafe({
          container: chatListContainer.value,
          element: el,
          block: 'nearest',
          behavior: 'instant',
        });
      }
    });
  }
}

function handleEnter() {
  if (selectedChatId.value) {
    selectAndNavigate({ chatId: selectedChatId.value });
  }
}

defineExpose({
  navigate,
  handleEnter,
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
      selectedChatId: exposedSelectedChatId,
    },
  }) || {}),
});

const selectedSearchResultItem = computed<Extract<SearchResultItem, { type: 'chat' }> | undefined>(() => {
  if (!selectedChat.value) return undefined;
  return {
    type: 'chat',
    chatId: idToRaw({ id: selectedChat.value.id }),
    title: selectedChat.value.title,
    updatedAt: selectedChat.value.updatedAt,
    matchType: 'title',
    contentMatches: [],
  };
});

watch(chats, nextChats => {
  if (nextChats.some(chat => chat.id === selectedChatId.value)) return;
  selectedChatId.value = nextChats[0]?.id ?? null;
}, { immediate: true });


import "virtual:naidan-tailwind-css-module/40fb60ab836fd5b437579f0a841d9bb568a10c6cff95673ee39c17494cc7c0fa.js";
import "virtual:naidan-tailwind-css-module/69d3f89da3142837a4bf41b7a4d41941850c442adf8f9f43ef7bb05b3728dd83.js";
import "virtual:naidan-tailwind-css-module/6f506a4c0f543a091de5b53b381e587a6ba1c3c266800941cf9d0348e2f5ed30.js";
import "virtual:naidan-tailwind-css-module/c56eb9485a58466ea7abe8756bd42c6cc1345250ae5ce6b0881993e5da96567c.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/f014fe3dc00d3fb0284e070a7fc8c75d552e84a2d3c975497da974f942cac563.js";
import "virtual:naidan-tailwind-css-module/f9004e4bacdf86afb575355f988f793b2afd745c3bac6d2f33d6f5ff0aadcaee.js";
</script>

<template>
  <div tw-class="h-full flex flex-col bg-white dark:bg-gray-900">
    <!-- Group Info Bar (Top) -->
    <div tw-class="px-6 py-4 border-b border-gray-100 dark:border-gray-800 flex items-center justify-between bg-gray-50/50 dark:bg-gray-900/50 shrink-0">
      <div tw-class="flex items-center gap-3">
        <div tw-class="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-xl text-blue-600 dark:text-blue-400">
          <FolderIcon tw-class="w-5 h-5" />
        </div>
        <div>
          <h3 tw-class="text-sm font-black text-gray-900 dark:text-gray-100 tracking-wider">{{ groupName }}</h3>
          <p tw-class="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{{ lazyStrings.ChatGroupSearchPreview__group_preview() }}</p>
        </div>
      </div>
      <div tw-class="text-[10px] font-black text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 px-2 py-1 rounded-lg">
        {{ lazyStrings.ChatGroupSearchPreview__chat_count({ count: chats.length }) }}
      </div>
    </div>

    <!-- Main Content Area -->
    <div tw-class="flex-1 flex overflow-hidden">
      <!-- Left: Chat List inside Group -->
      <div tw-class="w-64 border-r border-gray-100 dark:border-gray-800 flex flex-col overflow-hidden bg-gray-50/30 dark:bg-gray-950/20 shrink-0">
        <div v-if="chats.length === 0" tw-class="flex-1 flex flex-col items-center justify-center p-6 text-center">
          <MessageSquareIcon tw-class="w-8 h-8 text-gray-200 dark:text-gray-800 mb-2" />
          <p tw-class="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{{ lazyStrings.ChatGroupSearchPreview__empty_group() }}</p>
        </div>
        <div v-else ref="chatListContainer" class="scrollbar-hide" tw-class="flex-1 overflow-y-auto p-3 space-y-1">
          <div
            v-for="chat in chats"
            :key="idToRaw({ id: chat.id })"
            @click="selectedChatId = chat.id"
            :data-group-chat-id="idToRaw({ id: chat.id })"
            :tw-class="['w-full h-12 flex items-center gap-3 px-3 rounded-xl transition-all cursor-pointer group relative overflow-hidden shrink-0', selectedChatId === chat.id
              ? 'bg-blue-50 dark:bg-blue-900/20 shadow-sm border border-blue-100/50 dark:border-blue-800/50'
              : 'hover:bg-gray-100 dark:hover:bg-gray-800/50 border border-transparent']"
          >
            <div tw-class="shrink-0 p-1.5 rounded-lg bg-white/50 dark:bg-gray-900/50">
              <MessageSquareIcon tw-class="w-3.5 h-3.5 text-gray-400" />
            </div>

            <div tw-class="flex-1 min-w-0 flex flex-col justify-center">
              <span :tw-class="['text-[11px] font-bold truncate', selectedChatId === chat.id ? 'text-blue-700 dark:text-blue-300' : 'text-gray-700 dark:text-gray-300']">
                {{ chat.title || lazyStrings.SHARED__new_chat() }}
              </span>
              <span tw-class="text-[8px] text-gray-400 font-medium truncate">{{ formatTime({ timestamp: chat.updatedAt }) }}</span>
            </div>

            <!-- Action Button (Doesn't change layout height) -->
            <button
              @click.stop="selectAndNavigate({ chatId: chat.id })"
              tw-class="shrink-0 p-1.5 rounded-lg bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 shadow-sm hover:text-blue-600 dark:hover:text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity"
              :title="lazyStrings.ChatGroupSearchPreview__open_chat()"
            >
              <ChevronRightIcon tw-class="w-3.5 h-3.5" />
            </button>

            <!-- Selection Indicator -->
            <div v-if="selectedChatId === chat.id" tw-class="absolute left-0 top-0 bottom-0 w-1 bg-blue-600 dark:bg-blue-500"></div>
          </div>
        </div>
      </div>

      <!-- Right: Detailed Chat Preview -->
      <div tw-class="flex-1 overflow-hidden relative bg-white dark:bg-gray-900">
        <SearchPreview
          v-if="selectedSearchResultItem"
          :chat="selectedSearchResultItem"
          tw-class="!border-l-0"
        />
        <div v-else tw-class="h-full flex items-center justify-center text-gray-300 p-8 text-center uppercase text-[10px] font-black tracking-[0.2em]">
          {{ lazyStrings.ChatGroupSearchPreview__select_a_chat_to_preview() }}
        </div>
      </div>
    </div>
  </div>
</template>

